Here’s a **super simple C++ code** that shows how **constructor** and **destructor** work — plain and clean 👇  

```cpp
#include <iostream>
using namespace std;

class Demo {
public:
    // Constructor
    Demo() {
        cout << "Constructor called!" << endl;
    }

    // Destructor
    ~Demo() {
        cout << "Destructor called!" << endl;
    }

    void show() {
        cout << "Hello from Demo class!" << endl;
    }
};

int main() {
    Demo obj;   // Object created → constructor runs
    obj.show(); // Call member function
    // When main ends → destructor runs automatically
    return 0;
}
```

### 🧠 Output:
```
Constructor called!
Hello from Demo class!
Destructor called!
```

